from audit_common import *
def md(frame):
    frame=frame.copy()
    for key in frame.select_dtypes('number'):
        frame[key]=frame[key].map(lambda x:f'{x:.6f}' if isinstance(x,(float,np.floating)) else str(x))
    return '\n'.join(['| '+' | '.join(frame.columns)+' |','| '+' | '.join(['---']*len(frame.columns))+' |']+['| '+' | '.join(map(str,row))+' |' for row in frame.itertuples(index=False,name=None)])+'\n'
def main():
    check_protocol();assert read(P/'outputs/INDEPENDENT_NUMERIC_VERIFICATION.json')['status']=='PASS';assert read(P/'outputs/HISTORICAL_PROTECTION.json')['status']=='PASS'
    contrib=rd(P/'outputs/EVENT_SSE_CONTRIBUTIONS.csv');combined=contrib.loc[contrib.event=='COMBINED'];f2=combined.loc[combined.model=='F2'];rawbins=rd(P/'outputs/RAW_BIN_MIXTURE_RECOMPUTATION.csv');low=rawbins.loc[rawbins.row_id.isin([3113,3628])]
    analog=rd(P/'outputs/HISTORICAL_STOP_MORPHOLOGY_ANALOGS.csv');counts=analog.groupby('partition').agg(observed=('row_id','size'),legal_targets=('used_as_forecast_target','sum')).reset_index()
    near=rd(P/'outputs/NEAREST_HISTORY_ONLY_MATCHES.csv');gate=rd(P/'outputs/GATE_PATH_STATISTICS.csv');gfocus=rd(P/'outputs/EVENT_GATE_TRAIN_SUPPORT.csv');pair=rd(P/'outputs/PAIR_INVERSION_SUMMARY.csv');lags=rd(P/'outputs/ALL_STOP_LOCAL_TIMING.csv');diff=rd(P/'outputs/MATCHED_F2_BASELINE_DIFFERENCES.csv');similar=rd(P/'outputs/CORE_AND_CONTEXT_SIMILARITY.csv')
    ordinary=lags.loc[(lags.model=='F2')&~lags.core_event];zero=int((ordinary.lag_rows==0).sum());total=len(ordinary)
    compact=combined[['model','seed','formal_RMSE_mV','query_weighted_SSE_share_pct','target_time_equal_MSE_share_pct']]
    cs('outputs/REPORT_MAIN_NUMBERS.csv',compact)
    intro=f'# F2后段极端误差专项诊断（探索性）\n\n基准提交：`{check_protocol()["base_commit"]}`。只读五模型×固定42/52/62，沿用原548个后段起点、13152条查询、640个唯一目标时刻。两组事件由研究负责人指定；不是独立Test，也不是事前确认性假设检验。\n\n'
    answers=f'''A. **已证实：误差高度集中于两次启停混合桶的相邻状态切换。** 四个目标时刻占640个唯一目标的0.625%，每Seed涉及96/13152条查询（0.730%），却贡献F2的{f2.query_weighted_SSE_share_pct.min():.3f}%～{f2.query_weighted_SSE_share_pct.max():.3f}%后段平方误差。按唯一目标等权后仍为{f2.target_time_equal_MSE_share_pct.min():.3f}%～{f2.target_time_equal_MSE_share_pct.max():.3f}%。这是两个物理事件，不是96个独立事件。

B. **已证实：Train和Validation有可比先例。** 按“零电流占比>0.5、前后桶零电流占比为0、有效且同segment”这一描述性定义，Train有107个，84个进入合法预测目标；Validation有16个，12个进入合法预测目标。最近历史输入匹配也找到相似的48步工况，但对应未来低谷有第12步和第13步两种身份。不能称为完全未见过的新退化模式。

C. **已证实：这两次事件出现一致的局部提前一格。** 每Seed、每事件23/23个完整高低配对起点发生预测高低顺序颠倒；19/19个覆盖六点邻域的起点，其预测低谷比真实低谷早1个聚合行，即0.5运行小时。三个Seed合计114个重叠诊断窗口均如此，不能当作114个独立事件。其他启停事件的F2诊断窗口{zero}/{total}（{zero/total*100:.3f}%）为零滞后，因此不是全文件标签整体错一行，也不能称为后段普遍提前。

D. **已证实“F2在这些事件中更差”，尚无法判断“双路径融合或门控导致更差”。** 完全匹配的四目标查询中，F2在三个Seed上的平方误差都高于F0、F1、LSTM、TCN；但LSTM Seed52也有同类提前，F1的部分Seed亦失败。F1/F2冻结权重经过不同训练轨迹，不能用它们的差值单独识别门控因果作用。只读观察没有发现gate饱和或超出Train范围；隐藏路径差异也在Train既有范围内。本轮未做门控替换、分支移除或新训练，不能把潜在机制解释升级成已证实原因。

E. **较可信的解释、值得下一步核查：运行时钟冻结、停机样本混合和下一次启停相位的可预测性。** 先审计仅依赖过去观测的时钟/周期相位线索能否区分“下一桶低谷”和“再下一桶低谷”，以及启停计划是否在起点实际可获得。使用现有Train/Validation的原始时间、OpHrs2、电流及既有窗口即可做最小只读研究；不先换网络或训练。若相似过去信息对应不同未来启停位置，或可用计划无记录，就停止声称精确切换可在线确定；保持正式协议和成绩不变。
'''
    write('README.md',intro+answers+'\n## 复现与文件\n\n```powershell\n# 使用既有项目Python环境，PYTHONUTF8=1、PYTHONDONTWRITEBYTECODE=1\npython -B scripts/analyze.py\npython -B scripts/raw_event_check.py\npython -B scripts/extract_frozen_gates.py\npython -B scripts/complete_diagnostics.py\npython -B scripts/verify.py\npython -B scripts/plot_figures.py\npython -B scripts/write_reports.py\npython -B scripts/seal.py\n```\n\n以上在本阶段目录运行。configs已保存身份，不能重冻结；所有写入限制在本目录。原始读取只流式扫描两个已暴露事件的现有Loadcycle文件，仅保留每事件四桶12210条真实样本；不运行旧一次性评价程序。门控仅采集原始输出，先要求Train/Validation/后段预测逐点严格复现，再验证hook不改变预测与权重。\n\n主证据为EVENT_SSE_CONTRIBUTIONS.csv、POINTWISE_ERRORS.csv、RAW_BIN_MIXTURE_RECOMPUTATION.csv、PAIR_INVERSION_SUMMARY.csv、ALL_STOP_LOCAL_TIMING.csv、NEAREST_HISTORY_ONLY_MATCHES.csv和FORWARD_IDENTITY_AUDIT.csv。所有查询均保留。七套图均来自真实CSV，PNG300dpi及PDF配套，代码及最终SHA见DELIVERY_MANIFEST。\n')
    write('01_极端误差来源分析.md',intro+'## 两事件对全体后段平方误差的贡献\n\n'+md(compact)+'\nquery加权的分母为所有13152条查询的平方误差之和；target-time-equal先对每个目标的所有起点误差平方求均值，再对640个唯一目标等权。四个核心目标每个恰有24条查询，边界/缺口附近其他目标不足24条，所以两种比例不同。两种口径下仍高度集中，不是单纯重叠计数造成的假象。\n\n按目标、步长、起点分别完整保存PER_TARGET_ERRORS.csv、PER_HORIZON_ERRORS.csv、PER_ORIGIN_ERRORS.csv；三种分解均守恒到原正式SSE。核心目标的错误分布在多个起点及1～24步，并非只有12h终点出错。不得把同一目标的24个起点当作24次独立失效。\n\n## 仅供诊断的代数敏感性\n\n'+md(f2[['seed','formal_RMSE_mV','POSTHOC_remainder_RMSE_not_new_formal_score']])+'\n右列只是从完整SSE中分出核心贡献后的剩余误差量，不是重新筛样本的成绩，不重新排名、不替换正式RMSE。即使看剩余量仍约19～22mV，不能据此宣布后段问题已被解决。原始预测、排名、全体目标均未修改。\n')
    write('02_原始工况与状态切换.md',intro+'## 秒级数据直接复算\n\n'+md(low)+'\n两低桶都包含6810条样本，其中5006条满足|I|≤0.1A、1804条不满足。该阈值来自冻结N1聚合配置，不是本轮按误差调整。非零电流样本均值约0.732V，零电流样本约0.019～0.020V，按样本比例混合恰好得到原0.208V桶标签。非零集合包含少量启停瞬态，不能将其另称稳定健康参考或新SOH标签。\n\n原始OpHrs2在停机段固定于1873.5h/2149.5h，日历时间继续推进。N1按floor((OpHrs2+1e-10)/0.5)分桶，cell_voltage_mean对全部样本求均值；因此0.5运行小时桶可以跨1.891389个日历小时，coverage_ratio=3.783333，而不是样本缺失率异常。coverage的旧有效规则只排除不足覆盖和内部缺口，不排除大于1的覆盖，故这些桶有效、segment为18/19且邻接日历采样连续。\n\n数据行身份没有出错：3112/3113对应bin_end 1873.5/1874.0，3627/3628对应2149.5/2150.0。低桶的bin_start恰在1873.5/2149.5；不能把bin_end与原始停机瞬间混为同一个时钟点。0.5运行小时的预测提前，不等于严格提前30分钟日历时间。\n\n## 两次事件相似性\n\n'+md(similar)+'\n核心六点电压RMSE约0.284mV、电流约0.322A，零电流占比完全相同；完整前后50点并非完全相同，存在其他启停位置和局部工况差异，不能把整段称为完全复制。完整原始字段和时钟证据见EVENT_50_ROW_CONTEXT、RAW_EVENT_SAMPLES、RAW_STATE_RUNS及RAW_SOURCE_IDENTITY。没有用低电压直接认定不可逆衰退。\n\n## 既有先例\n\n'+md(counts)+'\n这些是聚合形态先例，不是独立寿命轨迹；部分靠近无效窗口或分区边界，不能形成合法预测目标。保持原资格规则，没有新增、补造或放宽样本。\n')
    write('03_F2与基线模型对照.md',intro+'## 相同键下的误差\n\n全部origin_row/target_row/horizon_step/y_true逐点严格相等。\n\n'+md(diff.loc[diff.subset=='FOUR_CORE_TARGETS',['seed','baseline','queries','F2_minus_baseline_SSE_mV2','F2_abs_error_smaller_queries','F2_abs_error_larger_queries']])+'\nF2在四目标总SSE上对每个基线、每个Seed均更差，是明确的不利证据，不能因其某些单点较好而隐藏。\n\n## 高低顺序颠倒\n\n'+md(pair)+'\n配对比较必须同一起点同时预测两个目标，所以每事件23个配对起点，而非每目标24条查询。局部六点最低位置再要求完整六点覆盖，每事件每Seed19个。F2三个Seed在两事件均为23/23颠倒、19/19提前一行；LSTM52同样失败。图04固定相同起点3100/3615展示六点，未择优筛窗口、未拼接不同预测。\n\n原始标签键严格正确，且其他启停点绝大多数零滞后，因此是事件局部的预测相位/状态错误，不是所有预测统一错位。不能通过整体平移预测来修正正式成绩。没有计算或推荐这种事后校正预测。\n')
    write('04_融合机制与可能原因.md',intro+'## 真实信息流\n\n历史14槽位经固定Top10掩码与因果EWMA/Train-only scaler进入原生TFT VSN。VSN encoder输出同时进入LSTM encoder和左填充因果卷积分支（核3、dilation1/4，单层感受野3/9个历史位置，后接pointwise、dropout和残差归一化）。\n\n门控取五项标准化历史输入的48步均值，经过5→8→1、ELU和sigmoid，得到每个窗口一个标量g。融合是g×encoder_LSTM+(1−g)×encoder_CNN；发生在post-LSTM encoder张量、static enrichment和Attention之前。decoder原始工况通道为零且不参与decoder VSN，只使用确定的相对步坐标。一个g不等于24个独立门控，也不直接输出每步电压；不能把隐藏路径RMS映射成某路径预测了0.2V。\n\n## 原始门控观测\n\n'+md(gate)+'\n'+md(gfocus[['seed','event','origins','g_mean','g_min','g_max','outside_Train_g_range','outside_Train_path_difference_range']])+'\nSeed42、62有更明显的g变化，Seed52更接近固定约0.488，但三个Seed都发生同样的局部提前。事件g及隐藏路径差异均未超出Train范围，没有出现接近0/1的饱和证据。范围内不代表机制一定正常，也不能反过来证明机制导致错误。\n\n本轮9组Train/Validation/LATE_LIFE原始前向均与冻结缓存严格一致；只读hook再次前向结果仍严格相同，权重SHA未变，hook均移除，没有替换门控、替换分支或运行backward/optimizer。此前六优秀Seed门控审计主要是Validation、且种子范围不同，不能直接当作当前后段的反事实证据。\n\n## 可用性与归因边界\n\n较可信解释：模型在重复启停模板上学到固定相位，而实际运行时钟冻结及桶边界使两次事件的低桶落在相邻行；历史近邻的未来低谷有第12/13步两种身份。最近Train邻居也存在正确的第13步低谷，所以不能将错误简单归为“训练从未见过”或“任何模型都不可能预测”。当前14变量不包含未来启停计划，门控的历史均值也无独立的下一次启停计划。\n\n尚无法判断：未来启停安排在真实预测起点是否可事先获知、过去历史是否仍包含可被更好利用的相位线索、融合路径各自的因果贡献，以及固定g能否改善这些事件。F1/F2训练后的其余权重不同，仅比较冻结模型不能认定新增门控失效。本轮不补做干预训练或自动扩展模型。\n')
    write('05_最终结论及后续建议.md',intro+answers+'\n## 最小后续研究与停止条件\n\n下一项优先为“已有Train/Validation启停相位与双时钟标签可预测性审计”，不是新的网络训练。使用N1源分桶代码、原始DateTime/OpHrs2/电流、已冻结48步历史及未来启停记录，区分计划性和事后才可知的停机。先固定从过去获取的时钟/相位线索与记录可用性；只做时间身份和相似历史的条件歧义核查，不把事后零电流比例作为输入。\n\n最小规模：复用已识别107/16个Train/Validation形态先例及84/12个合法目标，优先查清桶边界附近的启停位置。若不存在起点可用的计划，或者相近历史仍出现不可区分的两种停机位置，就停止“确定下一桶切换”的主张，不立即增大backbone或搜索新Seed。是否需要独立训练的门控消融，应在该信息缺口解决后另行授权；本轮不能提供它的成绩。\n\n本次正式评价口径、历史论文结论、Phase L独立Test不合格结论保持不变。完成后停止。\n')
    js('outputs/FINAL_INTERPRETATION.json',dict(A='CONFIRMED_EVENT_CONCENTRATION',B='CONFIRMED_COMPARABLE_HISTORICAL_PRECEDENTS',C='CONFIRMED_LOCAL_ONE_BIN_EARLY_NOT_GLOBAL_ALIGNMENT_ERROR',D='CONFIRMED_F2_WORSE_ASSOCIATION_CAUSAL_GATE_EFFECT_UNDETERMINED',E='RECOMMEND_CLOCK_AND_STOP_PHASE_PREDICTABILITY_AUDIT_NO_NEW_TRAINING',query_weighted_F2_event_share_pct=f2.query_weighted_SSE_share_pct.tolist(),target_equal_F2_event_share_pct=f2.target_time_equal_MSE_share_pct.tolist(),other_F2_stop_zero_lag=dict(zero=zero,total=total),physical_events=2,formal_predictions_modified=False))
